-- K14 – closer changes before r5-h1c (DOM FB-R5-DOM-ARC-1H-01, SEC FB-R5-SEC-ARC-1I-02, contract 0.3.13 1.30).
-- Runbook v1.0.5 K14. Run ONLY through the k14-run block that SEC pinned, as ottimo_readonly, once r5-h1c (#154) is
-- live on production. READ ONLY, ends with ROLLBACK. Prints constant labels and counts only: never a name, an id, a
-- booking code, a date, an amount, a rate, a reason or a guest column. Do not edit this file, not even a comment:
-- one byte changes its SHA-256 and the pinned block stops.
-- Source of the closer history: reservation_change (field closer_user_id), not audit_event reservation.closer_changed
-- (before r5-h1c its before/after were empty). Reads tables and columns that exist since v1.0.4.
BEGIN TRANSACTION READ ONLY;
SELECT 1 AS guard
 WHERE (CASE
          WHEN NOT COALESCE((SELECT r.rolbypassrls OR r.rolsuper FROM pg_roles r WHERE r.rolname = current_user), false)
               AND COALESCE(current_setting('app.property_id', true), '') = ''
            THEN 'k14 check stopped: run as ottimo_readonly (BYPASSRLS) - under RLS without a tenant nothing shows'
          WHEN NOT EXISTS (SELECT 1 FROM property)
            THEN 'k14 check stopped: no property is visible'
          ELSE 'false'
        END)::boolean;
-- (1) List 1: bookings whose closer was changed, or first set, at or after the real check-in. One booking counts
--     once, however many changes. Split by the booking status now:
--     in_house    - the owner decides BEFORE check-out (at check-out r5-h1c gives the commission to the new closer);
--     checked_out - the owner pays the right person at the next pay-out (BR-903 (3));
--     other       - any other status (should be 0: a checked-in booking is in_house or checked_out).
WITH l1 AS (
  SELECT DISTINCT rv.id AS booking, rv.status
    FROM reservation_change ch
    JOIN reservation rv ON rv.id = ch.reservation_id AND rv.property_id = ch.property_id
   WHERE ch.field = 'closer_user_id'
     AND rv.actual_checkin_at IS NOT NULL
     AND ch.changed_at >= rv.actual_checkin_at
)
SELECT v.count_of, v.n
  FROM (SELECT count(*) AS total,
               count(*) FILTER (WHERE status = 'in_house') AS in_house,
               count(*) FILTER (WHERE status = 'checked_out') AS checked_out,
               count(*) FILTER (WHERE status NOT IN ('in_house', 'checked_out')) AS other
          FROM l1) s
 CROSS JOIN LATERAL (VALUES (1, 'closer_changed_after_checkin', s.total),
                            (2, 'closer_changed_after_checkin_in_house', s.in_house),
                            (3, 'closer_changed_after_checkin_checked_out', s.checked_out),
                            (4, 'closer_changed_after_checkin_other_status', s.other)) AS v(o, count_of, n)
 ORDER BY v.o;
-- (2) List 2: bookings with a live commission row of the booking (reservation_id set, not void) whose payee is not
--     the booking's closer now. Split by the row status only (SEC 129: never by payee type or by person):
--     earned_payable_paid - the owner pays the right person at the next pay-out (outside the Desk, as today);
--     projected           - a row not earned yet;
--     projected_auto      - part of projected: the booking is not checked out, not cancelled or no-show, and not in
--                           list 1, so r5-h1c re-syncs the row at check-out (ensureCommission) - nothing to do.
WITH l1 AS (
  SELECT DISTINCT ch.reservation_id AS booking
    FROM reservation_change ch
    JOIN reservation rv ON rv.id = ch.reservation_id AND rv.property_id = ch.property_id
   WHERE ch.field = 'closer_user_id'
     AND rv.actual_checkin_at IS NOT NULL
     AND ch.changed_at >= rv.actual_checkin_at
), m AS (
  SELECT rv.id AS booking, rv.status AS booking_status, cm.status AS row_status
    FROM commission cm
    JOIN reservation rv ON rv.id = cm.reservation_id AND rv.property_id = cm.property_id
   WHERE cm.reservation_id IS NOT NULL AND cm.status <> 'void'
     AND cm.payee_user_id IS DISTINCT FROM rv.closer_user_id
)
SELECT v.count_of, v.n
  FROM (SELECT count(DISTINCT booking) AS total,
               count(DISTINCT booking) FILTER (WHERE row_status IN ('earned', 'payable', 'paid')) AS earned,
               count(DISTINCT booking) FILTER (WHERE row_status = 'projected') AS projected,
               count(DISTINCT booking) FILTER (WHERE row_status = 'projected'
                                                 AND booking_status IN ('hold', 'confirmed', 'in_house')
                                                 AND booking NOT IN (SELECT booking FROM l1)) AS projected_auto
          FROM m) s
 CROSS JOIN LATERAL (VALUES (1, 'payee_not_closer', s.total),
                            (2, 'payee_not_closer_earned_payable_paid', s.earned),
                            (3, 'payee_not_closer_projected', s.projected),
                            (4, 'payee_not_closer_projected_auto', s.projected_auto)) AS v(o, count_of, n)
 ORDER BY v.o;
ROLLBACK;
